  ('nang-diu', 'nang-diu', 'Nắng Dịu', 'Hướng dương vàng và lớp hoa nhỏ trắng nhẹ.', 'Ba bông hướng dương được gói cùng hoa nhỏ màu trắng và sắc xanh tự nhiên, vừa tươi sáng vừa gọn gàng.', 'Những ngày tươi sáng', 'standard', 590000, 'VND', 'available', '["Bán chạy"]', '["Vàng ấm","Trắng"]', '["Ấm áp","Rạng rỡ"]', '["Sinh nhật","Lời cảm ơn","Tặng không cần dịp"]', '["Hướng dương","Hoa nhỏ màu trắng","Foliage theo mùa"]', '[{"alt":"Bó Nắng Dịu với ba bông hướng dương và hoa nhỏ màu trắng","caption":null,"fit":"cover","position":"center 46%","poster":null,"src":"src/assets/hanapipi-photos/9d055925-4c58-4c97-8bb4-88714cc1468a.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 1, 1, 0, 'catalogue-2026-08-24-v1', '2026-08-18T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('du-am-hong', 'du-am-hong', 'Dư Âm Hồng', 'Hồng phấn, trắng ngà và nhiều lớp hoa mềm.', 'Những lớp hoa hồng dịu và trắng ngà được sắp theo dáng tròn đầy, phù hợp cho một lời yêu thương tinh tế.', 'Lời muốn nói', 'standard', 790000, 'VND', 'available', '[]', '["Hồng phấn","Trắng ngà"]', '["Lãng mạn","Dịu dàng"]', '["Yêu thương","Kỷ niệm","Tặng không cần dịp"]', '["Hoa hồng tông trắng và phấn","Cụm hoa tông hồng theo mùa","Foliage xanh"]', '[{"alt":"Bó Dư Âm Hồng với cụm hoa hồng dịu và hoa trắng ngà","caption":null,"fit":"cover","position":"center 46%","poster":null,"src":"src/assets/hanapipi-photos/ae7bf17a-f600-4378-9c5f-82004588994f.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 1, 1, 1, 'catalogue-2026-08-24-v1', '2026-08-10T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('may-trang', 'may-trang', 'Mây Trắng', 'Hoa hồng trắng và sắc xanh thanh mát.', 'Hoa hồng trắng đi cùng hoa nhỏ và foliage xanh, tạo nên một thiết kế sáng, thanh thoát cho những khởi đầu mới.', 'Khoảng trời trong', 'standard', 690000, 'VND', 'seasonal', '["Theo mùa"]', '["Trắng","Xanh lá"]', '["Trong trẻo","An lành"]', '["Khởi đầu mới","Lời cảm ơn","Chia sẻ"]', '["Hoa hồng trắng","Hoa nhỏ màu trắng","Foliage xanh theo mùa"]', '[{"alt":"Bó Mây Trắng với hoa hồng trắng, hoa nhỏ li ti và foliage xanh","caption":null,"fit":"cover","position":"center 45%","poster":null,"src":"src/assets/hanapipi-photos/0a16b3a9-6b5b-41a5-bb9f-c4f3e003ba0d.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 1, 1, 2, 'catalogue-2026-08-24-v1', '2026-08-15T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('vuon-som-mai', 'vuon-som-mai', 'Vườn Sớm Mai', 'Hồng phấn, xanh dịu và nhiều lớp hoa mềm.', 'Một thiết kế đầy đặn với sắc hồng phấn, xanh dịu và trắng kem, cân bằng giữa nét tươi sáng và mềm mại.', 'Khoảnh khắc dịu dàng', 'standard', 850000, 'VND', 'available', '[]', '["Hồng phấn","Xanh lam"]', '["Tươi mới","Tự nhiên"]', '["Sinh nhật","Khởi đầu mới","Yêu thương"]', '["Hoa tông hồng","Cụm hoa xanh dịu theo mùa","Foliage xanh"]', '[{"alt":"Bó Vườn Sớm Mai với hoa hồng phấn, xanh dịu và trắng kem","caption":null,"fit":"cover","position":"center 42%","poster":null,"src":"src/assets/hanapipi-photos/45c02138-3e6c-42f9-ac5c-40f748c868d2.jfif","type":"image"},{"alt":"Chi tiết những lớp hoa hồng phấn và xanh dịu của Vườn Sớm Mai","caption":null,"fit":"cover","position":"center 48%","poster":null,"src":"src/assets/hanapipi-photos/fca52819-999f-479f-af3f-bc046b4a18cb.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 1, 1, 3, 'catalogue-2026-08-24-v1', '2026-08-06T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('sac-apricot', 'sac-apricot', 'Ngày Hồng', 'Hồng sáng, trắng kem và nhịp hoa tươi.', 'Sắc hồng sáng được điểm bằng hoa trắng kem và foliage xanh, phù hợp cho sinh nhật hoặc một lời cảm ơn tươi vui.', 'Những ngày rực rỡ', 'standard', 650000, 'VND', 'available', '["Mới"]', '["Hồng phấn","Trắng"]', '["Vui tươi","Năng lượng"]', '["Sinh nhật","Chúc mừng","Lời cảm ơn"]', '["Hoa tông hồng và trắng","Cụm hoa theo mùa","Foliage xanh"]', '[{"alt":"Bó Ngày Hồng với hoa tông hồng sáng và trắng kem","caption":null,"fit":"cover","position":"center 44%","poster":null,"src":"src/assets/hanapipi-photos/41cd6826-4f50-40cd-9b08-32438e216342.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 4, 'catalogue-2026-08-24-v1', '2026-08-22T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('dem-nhe', 'dem-nhe', 'Đêm Nhẹ', 'Hoa hồng đỏ đậm, điểm hoa trắng nhỏ.', 'Hoa hồng đỏ đậm được bó dày, điểm bằng những cành hoa trắng nhỏ để tổng thể mạnh mẽ mà vẫn thanh thoát.', 'Lời muốn nói', 'standard', 920000, 'VND', 'preorder', '["Đặt trước"]', '["Đỏ","Trắng"]', '["Sâu lắng","Lãng mạn"]', '["Yêu thương","Kỷ niệm","Chia sẻ"]', '["Hoa hồng đỏ","Hoa nhỏ màu trắng","Foliage xanh"]', '[{"alt":"Bó Đêm Nhẹ cỡ lớn với hoa hồng đỏ đậm và hoa nhỏ màu trắng","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/c0a70a74-4bba-447a-a25c-a5c26bf8b669.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 5, 'catalogue-2026-08-24-v1', '2026-08-20T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('ban-mai-xanh', 'ban-mai-xanh', 'Ban Mai Xanh', 'Xanh lam, trắng và một dáng bó gọn.', 'Sắc xanh lam đi cùng hoa nhỏ màu trắng trong một dáng bó gọn, mang cảm giác nhẹ và hiện đại.', 'Khoảng trời trong', 'standard', 560000, 'VND', 'available', '[]', '["Xanh lam","Trắng"]', '["Thanh mát","Bình yên"]', '["Khởi đầu mới","Chia sẻ","Tặng không cần dịp"]', '["Cụm hoa xanh lam theo mùa","Hoa nhỏ màu trắng","Foliage xanh"]', '[{"alt":"Bó Ban Mai Xanh với cụm hoa xanh lam và hoa nhỏ màu trắng","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/4f55637f-62c1-4c4a-86b9-1a0a91d53b7d.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 6, 'catalogue-2026-08-24-v1', '2026-08-21T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('gio-hoa-nhe', 'gio-hoa-nhe', 'Gió Hoa Nhẹ', 'Xanh lam, hồng phấn và trắng ngà cân bằng.', 'Những cụm hoa xanh lam được cân bằng bằng sắc hồng phấn và trắng ngà, vừa dịu dàng vừa có điểm nhấn.', 'Khoảnh khắc dịu dàng', 'standard', 740000, 'VND', 'available', '[]', '["Xanh lam","Hồng phấn"]', '["Nhẹ nhàng","Tự nhiên"]', '["Tặng không cần dịp","Lời cảm ơn","Sinh nhật"]', '["Cụm hoa xanh lam theo mùa","Hoa tông hồng và trắng","Foliage xanh"]', '[{"alt":"Bó Gió Hoa Nhẹ với sắc xanh lam, hồng phấn và trắng ngà","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/8f4bc810-e1dd-4fa0-8094-9436d1872ec7.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 7, 'catalogue-2026-08-24-v1', '2026-08-12T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('five-red-roses', 'five-red-roses', 'Năm Đóa Hồng', 'Năm bông hồng đỏ, gọn và rõ nét.', 'Một dáng bó nhỏ với năm bông hồng đỏ và foliage xanh, phù hợp cho lời nhắn giản dị nhưng có chủ ý.', 'Lời muốn nói', 'standard', 390000, 'VND', 'available', '[]', '["Đỏ","Xanh lá"]', '["Lãng mạn","Ấm áp"]', '["Yêu thương","Lời cảm ơn","Tặng không cần dịp"]', '["Năm bông hồng đỏ","Foliage xanh theo mùa"]', '[{"alt":"Bó năm bông hồng đỏ cùng foliage xanh trong lớp giấy trắng","caption":null,"fit":"cover","position":"center 40%","poster":null,"src":"src/assets/hanapipi-photos/11e6ab96-b808-4da3-81cd-737f39fc97c3.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 8, 'catalogue-2026-08-24-v1', '2026-08-23T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('strawberry-bunny-gift', 'strawberry-bunny-gift', 'Quà Ngọt', 'Dâu tây, hoa trắng và những chiếc nơ đỏ.', 'Một bó quà vui mắt kết hợp dâu tây với hoa trắng tạo hình, thích hợp cho sinh nhật hoặc món quà bất ngờ.', 'Những ngày rực rỡ', 'standard', 520000, 'VND', 'preorder', '["Mới"]', '["Đỏ","Trắng"]', '["Vui tươi","Rạng rỡ"]', '["Sinh nhật","Chúc mừng","Tặng không cần dịp"]', '["Dâu tây","Hoa trắng tạo hình","Nơ đỏ"]', '[{"alt":"Bó quà với dâu tây, hoa trắng tạo hình và nơ đỏ","caption":null,"fit":"cover","position":"center 44%","poster":null,"src":"src/assets/hanapipi-photos/42fdaebb-daa5-4b66-87cd-56b4666bd3ba.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 9, 'catalogue-2026-08-24-v1', '2026-08-23T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('no-watering-flower', 'no-watering-flower', 'Bông Hoa Không Cần Tưới', 'Không cần tưới, chỉ cần được dỗ đúng lúc.', 'Phiên bản giới hạn với biểu cảm khó đoán, năng lượng nhây tự nhiên và khả năng khiến người tặng tự giác xin lỗi dù chưa biết mình sai ở đâu.', 'Phiên bản chỉ có một', 'priceless', NULL, 'VND', 'preorder', '["Phiên bản 1/1"]', '["Hồng phấn","Xám"]', '["Đáng yêu","Tinh nghịch"]', '["Yêu thương","Tặng không cần dịp","Lời cảm ơn"]', '["Một biểu cảm phiên bản giới hạn","Một cây cọ trang điểm","Năng lượng nhây tự nhiên"]', '[{"alt":"Bông hoa vô giá thuộc bộ sưu tập chỉ để ngắm.","caption":null,"fit":"contain","position":"center","poster":null,"src":"src/assets/hanapipi-photos/bcaa9546-c4be-416d-9bf7-454eb2fd3b8b.jfif","type":"image"},{"alt":"Một khoảnh khắc riêng của bông hoa vô giá trong không gian âm nhạc.","caption":"Một chiều rất riêng, vẫn thuộc bộ sưu tập chỉ để ngắm.","fit":"cover","position":"center 48%","poster":null,"src":"src/assets/hanapipi-photos/personal-gallery/personal-flower-memory-01.jpg","type":"image"},{"alt":"Bông hoa thuộc bộ sưu tập chỉ để ngắm giữa khu vườn mùa lễ hội.","caption":"Một chút sắc đỏ dành riêng cho bộ sưu tập không restock.","fit":"cover","position":"center 42%","poster":null,"src":"src/assets/hanapipi-photos/personal-gallery/personal-flower-memory-02.jpg","type":"image"},{"alt":"Một thước phim riêng của bông hoa vô giá.","caption":"Khoảnh khắc chuyển động, đã được giữ yên phần âm thanh.","fit":"contain","position":"center","poster":"src/assets/hanapipi-photos/personal-gallery/personal-flower-video-01-poster.jpg","src":"src/assets/hanapipi-photos/personal-gallery/personal-flower-video-01.mp4","type":"video"}]', 'Cho ăn đúng giờ, dỗ dành nhẹ nhàng và tuyệt đối không mở đầu bằng câu “Em giận à?”.', 'Chỉ giao cho người đủ can đảm nhận quà; lịch giao còn tùy tâm trạng của “bông hoa”.', 0, 1, 10, 'catalogue-2026-08-24-v1', '2026-08-23T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('blush-atelier', 'blush-atelier', 'Hồng Sương', 'Hồng phấn, trắng ngà và sắc xanh nhẹ.', 'Những lớp hoa tông phấn và trắng ngà được bó mềm, giữ cảm giác tự nhiên và vừa vặn cho nhiều dịp tặng.', 'Khoảnh khắc dịu dàng', 'standard', 680000, 'VND', 'available', '[]', '["Hồng phấn","Trắng ngà"]', '["Dịu dàng","Tự nhiên"]', '["Sinh nhật","Lời cảm ơn","Tặng không cần dịp"]', '["Hoa tông hồng và trắng","Hoa theo mùa","Foliage xanh"]', '[{"alt":"Bó Hồng Sương với hoa hồng phấn, trắng ngà và foliage xanh","caption":null,"fit":"cover","position":"center 44%","poster":null,"src":"src/assets/hanapipi-photos/49ce5412-ca99-45e1-8347-b8b6e8957cf1.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 11, 'catalogue-2026-08-24-v1', '2026-08-19T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('grand-white-roses', 'grand-white-roses', 'Vườn Trắng', 'Hoa hồng trắng cỡ lớn và foliage thanh mát.', 'Một bó hoa hồng trắng đầy đặn, điểm hoa nhỏ và foliage xanh trong lớp giấy gói sáng màu.', 'Khoảng trời trong', 'standard', 890000, 'VND', 'preorder', '["Đặt trước"]', '["Trắng","Xanh lá"]', '["Thanh lịch","An lành"]', '["Khởi đầu mới","Chúc mừng","Chia sẻ"]', '["Hoa hồng trắng","Hoa nhỏ màu trắng","Foliage xanh theo mùa"]', '[{"alt":"Bó Vườn Trắng cỡ lớn với hoa hồng trắng và foliage xanh","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/4a543021-ea8d-41ab-b921-e1b062334cfd.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 12, 'catalogue-2026-08-24-v1', '2026-08-17T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('blue-wrapped-blush', 'blue-wrapped-blush', 'Hồng Ban Mai', 'Hồng phấn, trắng dịu và lớp giấy xanh nổi bật.', 'Sắc hoa hồng phấn và trắng được đặt trong lớp giấy xanh, tạo một tổng thể tươi nhưng không quá rực.', 'Những ngày tươi sáng', 'standard', 620000, 'VND', 'available', '[]', '["Hồng phấn","Trắng","Xanh lam"]', '["Tươi mới","Dịu dàng"]', '["Sinh nhật","Lời cảm ơn","Chúc mừng"]', '["Hoa hồng tông phấn","Hoa trắng theo mùa","Foliage xanh"]', '[{"alt":"Bó Hồng Ban Mai với hoa hồng phấn và trắng trong lớp giấy xanh","caption":null,"fit":"cover","position":"center 44%","poster":null,"src":"src/assets/hanapipi-photos/4e295c8e-4bd7-489b-8bbc-3485e350a064.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 13, 'catalogue-2026-08-24-v1', '2026-08-16T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('blue-meadow', 'blue-meadow', 'Mùa Xanh', 'Xanh lam, trắng và chiếc nơ xanh mềm.', 'Một thiết kế xanh lam và trắng có dáng rộng tự nhiên, hoàn thiện bằng nơ xanh cùng tông.', 'Khoảng trời trong', 'standard', 680000, 'VND', 'seasonal', '["Theo mùa"]', '["Xanh lam","Trắng"]', '["Thanh mát","Bình yên"]', '["Khởi đầu mới","Chia sẻ","Tặng không cần dịp"]', '["Cụm hoa xanh lam theo mùa","Hoa trắng theo mùa","Foliage xanh"]', '[{"alt":"Bó Mùa Xanh với cụm hoa xanh lam và trắng cùng nơ xanh","caption":null,"fit":"contain","position":"center","poster":null,"src":"src/assets/hanapipi-photos/60e6dad8-bd92-4b9b-83bb-466ef6035ee6.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 14, 'catalogue-2026-08-24-v1', '2026-08-14T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('classic-red-roses', 'classic-red-roses', 'Hồng Đỏ Cổ Điển', 'Hoa hồng đỏ và lớp hoa nhỏ màu trắng.', 'Một bó hồng đỏ theo dáng cổ điển, được làm nhẹ bằng hoa nhỏ màu trắng và lớp giấy xanh nhạt.', 'Lời muốn nói', 'standard', 760000, 'VND', 'available', '[]', '["Đỏ","Trắng"]', '["Lãng mạn","Sâu lắng"]', '["Yêu thương","Kỷ niệm","Chia sẻ"]', '["Hoa hồng đỏ","Hoa nhỏ màu trắng","Foliage xanh"]', '[{"alt":"Bó hoa hồng đỏ cổ điển cùng hoa nhỏ màu trắng và giấy xanh nhạt","caption":null,"fit":"cover","position":"center 34%","poster":null,"src":"src/assets/hanapipi-photos/7c5b31b5-e724-413d-9654-6b7774972a8c.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 15, 'catalogue-2026-08-24-v1', '2026-08-13T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('soft-pink-roses', 'soft-pink-roses', 'Sương Hồng', 'Hoa hồng phấn và foliage xanh nhẹ.', 'Sắc hồng phấn được bó theo dáng tròn mềm, điểm foliage xanh và hoa nhỏ để giữ tổng thể thoáng.', 'Khoảnh khắc dịu dàng', 'standard', 690000, 'VND', 'available', '[]', '["Hồng phấn","Xanh lá"]', '["Dịu dàng","Lãng mạn"]', '["Yêu thương","Sinh nhật","Lời cảm ơn"]', '["Hoa hồng phấn","Hoa nhỏ theo mùa","Foliage xanh"]', '[{"alt":"Bó Sương Hồng với hoa hồng phấn và foliage xanh trong lớp giấy trắng","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/8ba5f461-1cd8-47ad-a09e-aed8b3d38e80.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 16, 'catalogue-2026-08-24-v1', '2026-08-11T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('pastel-cloud', 'pastel-cloud', 'Mây Phấn', 'Hồng phấn, xanh lam và trắng kem nhiều lớp.', 'Một bó hoa pastel đầy đặn với sắc hồng phấn, xanh lam và trắng kem, phù hợp cho những dịp cần sự mềm mại.', 'Khoảnh khắc dịu dàng', 'standard', 780000, 'VND', 'available', '[]', '["Hồng phấn","Xanh lam","Trắng"]', '["Dịu dàng","Tươi mới"]', '["Sinh nhật","Yêu thương","Chúc mừng"]', '["Hoa tông hồng và trắng","Cụm hoa xanh dịu theo mùa","Foliage xanh"]', '[{"alt":"Bó Mây Phấn với sắc hồng phấn, xanh lam và trắng kem","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/c0b9c0a4-8fc4-482e-b2ca-cfe4707dab96.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 17, 'catalogue-2026-08-24-v1', '2026-08-09T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('blue-pink-ribbon', 'blue-pink-ribbon', 'Dải Lụa Xanh', 'Xanh lam, hồng phấn và chiếc nơ hồng nhẹ.', 'Sắc xanh lam và hồng phấn được gói trong lớp giấy trong, hoàn thiện bằng một dải nơ hồng mềm.', 'Khoảng trời trong', 'standard', 720000, 'VND', 'available', '[]', '["Xanh lam","Hồng phấn"]', '["Thanh mát","Dịu dàng"]', '["Sinh nhật","Lời cảm ơn","Tặng không cần dịp"]', '["Cụm hoa xanh lam theo mùa","Hoa tông hồng và trắng","Foliage xanh"]', '[{"alt":"Bó Dải Lụa Xanh với hoa xanh lam, hồng phấn và nơ hồng","caption":null,"fit":"cover","position":"center 46%","poster":null,"src":"src/assets/hanapipi-photos/c4ac4a4d-d91d-4a17-aaf0-29e95394caa2.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 18, 'catalogue-2026-08-24-v1', '2026-08-08T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('gentle-white-pink', 'gentle-white-pink', 'Lời Chúc Nhỏ', 'Trắng, hồng nhạt và một dáng bó nhỏ gọn.', 'Một bó hoa nhỏ với sắc trắng và hồng nhạt, phù hợp cho lời cảm ơn, lời chúc hoặc món quà nhẹ nhàng.', 'Lời muốn nói', 'standard', 460000, 'VND', 'available', '[]', '["Trắng","Hồng phấn"]', '["Nhẹ nhàng","Trong trẻo"]', '["Lời cảm ơn","Chia sẻ","Tặng không cần dịp"]', '["Hoa trắng theo mùa","Hoa tông hồng nhạt","Foliage xanh"]', '[{"alt":"Bó Lời Chúc Nhỏ với hoa trắng, hồng nhạt và nơ xanh","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/d48f02bc-4b0f-422d-8d00-01349439972e.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 19, 'catalogue-2026-08-24-v1', '2026-08-07T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('blush-rose-garden', 'blush-rose-garden', 'Vườn Hồng Phấn', 'Hồng phấn, trắng ngà và dáng bó tròn đầy.', 'Những lớp hoa phấn và trắng ngà được sắp dày vừa phải, tạo một bó hoa mềm và sáng trong lớp giấy trắng.', 'Khoảnh khắc dịu dàng', 'standard', 720000, 'VND', 'available', '[]', '["Hồng phấn","Trắng ngà"]', '["Dịu dàng","Lãng mạn"]', '["Yêu thương","Sinh nhật","Kỷ niệm"]', '["Hoa hồng tông phấn","Hoa trắng theo mùa","Foliage xanh"]', '[{"alt":"Bó Vườn Hồng Phấn với nhiều lớp hoa hồng phấn và trắng ngà","caption":null,"fit":"cover","position":"center 42%","poster":null,"src":"src/assets/hanapipi-photos/d68f0fff-be3f-4c1e-8af6-844f9ab0f9fc.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 20, 'catalogue-2026-08-24-v1', '2026-08-05T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('soft-pink-garden', 'soft-pink-garden', 'Hồng Êm', 'Hoa hồng phấn và những cành hoa trắng nhỏ.', 'Hoa hồng phấn được gói cùng hoa nhỏ màu trắng và foliage xanh, giữ dáng bó tự nhiên và dễ tặng.', 'Khoảnh khắc dịu dàng', 'standard', 690000, 'VND', 'available', '[]', '["Hồng phấn","Trắng"]', '["Nhẹ nhàng","Tự nhiên"]', '["Sinh nhật","Lời cảm ơn","Tặng không cần dịp"]', '["Hoa hồng phấn","Hoa nhỏ màu trắng","Foliage xanh"]', '[{"alt":"Bó Hồng Êm với hoa hồng phấn, hoa nhỏ màu trắng và foliage xanh","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/e40e61f7-3281-4064-af20-e08842412663.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 21, 'catalogue-2026-08-24-v1', '2026-08-04T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('happy-pastel', 'happy-pastel', 'Ngày Tươi', 'Hồng tươi, xanh dịu và trắng kem cân bằng.', 'Một thiết kế pastel tươi sáng với sắc hồng, xanh dịu và trắng kem, phù hợp cho sinh nhật hoặc lời chúc mừng.', 'Những ngày rực rỡ', 'standard', 760000, 'VND', 'available', '["Mới"]', '["Hồng phấn","Xanh lam","Trắng"]', '["Vui tươi","Tươi mới"]', '["Sinh nhật","Chúc mừng","Lời cảm ơn"]', '["Hoa tông hồng và trắng","Cụm hoa xanh dịu theo mùa","Foliage xanh"]', '[{"alt":"Bó Ngày Tươi với hoa hồng phấn, xanh dịu và trắng kem","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/ed53b488-db50-4f7b-977b-7a863b4ba2ba.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 22, 'catalogue-2026-08-24-v1', '2026-08-03T00:00:00.000Z', '2026-08-24T00:00:00.000Z'),
  ('grand-seasonal-arrangement', 'grand-seasonal-arrangement', 'Vườn Đỏ Kem', 'Kem, đỏ trầm và xanh theo mùa trong dáng lẵng lớn.', 'Một thiết kế lẵng hoa nhiều lớp với sắc kem, đỏ trầm và xanh theo mùa, phù hợp cho dịp chúc mừng trang trọng.', 'Thiết kế theo mùa', 'standard', 1290000, 'VND', 'preorder', '["Đặt trước"]', '["Đỏ","Trắng","Xanh lá"]', '["Ấm áp","Sâu lắng"]', '["Chúc mừng","Kỷ niệm","Chia sẻ"]', '["Hoa hồng tông kem và đỏ","Cụm hoa xanh theo mùa","Foliage xanh"]', '[{"alt":"Lẵng Vườn Đỏ Kem cỡ lớn với sắc kem, đỏ trầm và xanh theo mùa","caption":null,"fit":"cover","position":"center 43%","poster":null,"src":"src/assets/hanapipi-photos/fa411ea3-dd3e-4e6a-b4ee-f7dd36ef7f06.jfif","type":"image"}]', 'Đặt hoa nơi thoáng mát, thay nước mỗi ngày và cắt vát gốc hoa khoảng 1–2 cm.', 'Có thể giao trong ngày tại khu vực được hỗ trợ; thời gian sẽ được xác nhận theo địa chỉ.', 0, 1, 23, 'catalogue-2026-08-24-v1', '2026-08-02T00:00:00.000Z', '2026-08-24T00:00:00.000Z')
